parameters.jsonBody:
={
  "model": "openai/gpt-oss-20b",
  "messages": [
    {
      "role": "system",
      "content": "You are a news category classifier. Map the user's message to EXACTLY ANY of these 18 valid categories only: business, crime, domestic, education, entertainment, environment, food, health, lifestyle, other, politics, science, sports, technology, top, tourism, world, gaming ONLY.

Return ONLY valid JSON in the following format:

{"category":"technology"}

Rules:
- The category value must be one of the 18 listed above, in lowercase, exactly as spelled.
- Match the user's topic to the closest relevant category (e.g. cricket -> sports, AI or openai -> technology, election -> politics, stock market -> business).
- If the message mentions two clearly different topics
- If no topic is mentioned or it's unclear, default to {"category":"technology,sports"}.
- Do not include explanations or any text outside the JSON.

Examples:
User:Give me lastest update about ai
Output: {"category":"technology"}

User:latest tesla news
Output: {"category":"business"}

User:give news about cricket
Output: {"category":"sports"}

User:give me the news about tech and sports 
Output: {"category":"technology,sports"}"
    },
    {
      "role": "user",
      "content": "{{ $json.text }}"
    }
  ],
  "temperature": 0,
  "response_format": {
    "type": "json_object"
  }
}

parameters.jsCode:
const content = $input.first().json.choices?.[0]?.message?.content;

try {
  const parsed = JSON.parse(content);

  return [
    {
      json: {
        query: parsed.category || "technology,sports"
      }
    }
  ];
} catch (err) {
  return [
    {
      json: {
        query: "technology,sports"
      }
    }
  ];
}

const articles = $input.first().json.results;

const formatted = articles
  .slice(0, 20)
  .map((a, i) => `${i + 1}. ${a.title}\n${a.description || 'No description'}`)
  .join('\n\n');

return [{ json: { articles_text: formatted } }];

const text = $input.first().json.text;

const formatted = text.replace(/^- /gm, '• ');

return [{ json: { message: formatted } }];

const message = $input.first().json.message;

if (!message) {
  throw new Error("No 'message' field found");
}

const buffer = Buffer.from(message, "utf8");

return [
  {
    json: {
      filename: "news_report.md"
    },
    binary: {
      data: {
        data: buffer.toString("base64"),
        mimeType: "text/markdown",
        fileName: "news_report.md",
        fileExtension: "md"
      }
    }
  }
];
